slides.solution:
def split_bill(total, people):
    if people <= 0:
        raise ValueError("people must be at least 1")
    return round(total / people, 2)


print(split_bill(1000, 4))

slides.tests:
assert split_bill(1000, 4) == 250.0, f"split_bill(1000, 4) should be 250.0, not {split_bill(1000, 4)}."
assert split_bill(100, 3) == 33.33, f"split_bill(100, 3) should round to 33.33, not {split_bill(100, 3)}."
for bad in [0, -2]:
    try:
        split_bill(500, bad)
    except ValueError as e:
        assert str(e).strip(), "Give the ValueError a helpful message, like ValueError(\"people must be at least 1\")."
    except ZeroDivisionError:
        raise AssertionError(f"split_bill(500, {bad}) crashed with ZeroDivisionError. Check people first and raise ValueError yourself.")
    else:
        raise AssertionError(f"split_bill(500, {bad}) should raise ValueError, but it returned a value.")

